    getSyncedDeviceFunc: function getSyncedDeviceFunc() {
      var _this4 = this;
      if (!this.getSyncedTime || new Date().getTime() - this.getSyncedTime > 120000) {
        getSyncedDeviceApi(this.bastionDataId).then(function (res) {
          if (res.code === 200) {
            _this4.$message({
